function nfToEnglish(n){
  if(typeof n==='string'){ n = n.trim().replace(/,/g,''); }
  var neg=false;
  if(typeof n==='string'){ if(n.charAt(0)==='-'){ neg=true; n=n.slice(1); } }
  else if(typeof n==='number'){ if(n<0){ neg=true; n=-n; } }
  var parts=String(n).split('.');
  var intPart=parts[0]; var decPart=parts[1];
  if(!/^[0-9]+$/.test(intPart)) return {error:'Invalid number'};
  var ones=['','one','two','three','four','five','six','seven','eight','nine','ten',
            'eleven','twelve','thirteen','fourteen','fifteen','sixteen','seventeen','eighteen','nineteen'];
  var tens=['','','twenty','thirty','forty','fifty','sixty','seventy','eighty','ninety'];
  var scales=['','thousand','million','billion','trillion','quadrillion','quintillion'];
  function chunkToWords(num){
    if(num===0) return '';
    var s='';
    var h=Math.floor(num/100);
    if(h>0){ s+=ones[h]+' hundred'; }
    var r=num%100;
    if(r>0){
      if(s!=='') s+=' ';
      if(r<20) s+=ones[r];
      else { s+=tens[Math.floor(r/10)]; if(r%10>0) s+='-'+ones[r%10]; }
    }
    return s;
  }
  function groupWords(intStr){
    if(intStr==='0') return 'zero';
    var groups=[];
    while(intStr.length>0){ groups.unshift(intStr.slice(-3)); intStr=intStr.slice(0,-3); }
    var words=[];
    for(var g=0;g<groups.length;g++){
      var v=parseInt(groups[g],10);
      if(v===0) continue;
      var w=chunkToWords(v);
      if(scales[groups.length-1-g]!=='') w+=' '+scales[groups.length-1-g];
      words.push(w);
    }
    return words.join(' ');
  }
  var res=groupWords(intPart);
  if(decPart){
    var decWords=[];
    for(var i=0;i<decPart.length;i++){ var d=parseInt(decPart.charAt(i),10); decWords.push(ones[d]||String(d)); }
    res+=' point '+decWords.join(' ');
  }
  if(neg) res='negative '+res;
  return {value:res, error:null};
}
function nfToChineseCapital(n){
  if(typeof n==='string'){ n=n.trim().replace(/,/g,''); }
  var neg=false;
  if(typeof n==='string'){ if(n.charAt(0)==='-'){ neg=true; n=n.slice(1); } }
  else if(typeof n==='number'){ if(n<0){ neg=true; n=-n; } }
  if(typeof n==='number') n=String(n);
  if(!/^[0-9]+(\.[0-9]{1,2})?$/.test(n)) return {error:'Invalid number'};
  var digits='\u96f6\u58f9\u8d30\u53c1\u8086\u4f0d\u9646\u67d2\u634c\u7396';
  var units=['','\u62fe','\u4f70','\u4edf'];
  var bigUnits=['','\u4e07','\u4ebf'];
  var intStr=n.split('.')[0];
  var decStr=n.split('.')[1]||'';
  function intToCap(s){
    if(s==='0') return '\u96f6';
    s=s.replace(/^0+/,'')||'0';
    var len=s.length;
    var secs=[];
    while(s.length>0){ secs.unshift(s.slice(-4)); s=s.slice(0,-4); }
    var out='';
    for(var i=0;i<secs.length;i++){
      var sec=secs[i];
      var secWords='';
      var started=false;
      for(var p=0;p<sec.length;p++){
        var d=parseInt(sec.charAt(p),10);
        var pos=sec.length-1-p;
        if(d===0){
          if(started && !out.endsWith('\u96f6') && sectionHasNonZero(sec,p)){ /* handled below */ }
        } else { started=true; }
      }
      // straightforward per-digit with 零 handling
      var secStr=''; var zeroPending=false;
      for(var q=0;q<sec.length;q++){
        var dd=parseInt(sec.charAt(q),10);
        var pp=sec.length-1-q;
        if(dd===0){
          if(!zeroPending && (sectionHasNonZero(sec,q))) zeroPending=true;
        } else {
          if(zeroPending){ secStr+='\u96f6'; zeroPending=false; }
          secStr+=digits.charAt(dd)+units[pp];
        }
      }
      if(secStr!=='') out+=secStr+bigUnits[secs.length-1-i];
    }
    out=out.replace(/\u96f6+/g,'\u96f6').replace(/\u96f6\u4e07/g,'\u4e07').replace(/\u96f6\u4ebf/g,'\u4ebf');
    return out;
  }
  function sectionHasNonZero(sec, beforeIdx){
    for(var i=beforeIdx+1;i<sec.length;i++){ if(sec.charAt(i)!=='0') return true; }
    return false;
  }
  if(intStr==='0' && decStr==='') return {value:'\u96f6\u5143\u6574', error:null};
  var cap=intToCap(intStr);
  var tail='\u5143';
  if(decStr===''){ tail+='\u6574'; }
  else {
    var jiao=parseInt(decStr.charAt(0),10);
    var fen=decStr.length>1?parseInt(decStr.charAt(1),10):0;
    if(jiao>0) tail+=digits.charAt(jiao)+'\u89d2';
    else if(fen>0) tail+='\u96f6';
    if(fen>0) tail+=digits.charAt(fen)+'\u5206';
    if(fen===0) tail+='\u6574';
  }
  var val=(neg?'\u8d1f':'')+cap+tail;
  return {value:val, error:null};
}
if (typeof module !== 'undefined' && module.exports) {
  module.exports = { toEnglish:nfToEnglish, toChineseCapital:nfToChineseCapital };
}
if (typeof window !== 'undefined') {
  window.NumeralForgePure = { toEnglish:nfToEnglish, toChineseCapital:nfToChineseCapital };
}
